baseline_replay.probe:
import fs from 'node:fs';import path from 'node:path';import{pathToFileURL}from'node:url';import{createHash}from'node:crypto';import{execFileSync}from'node:child_process';
const root=process.cwd();const policy=await import(pathToFileURL(path.join(root,'_refs/harness/runtime-policy.mjs')));
const contract=JSON.parse(fs.readFileSync('_refs/harness/capability-contract.json','utf8'));
const options=['Approve','Change','Cancel'],localized=['Duyệt','Yêu cầu chỉnh sửa','Hủy'];const cases=[];
function probe(id,actual,check,expected){cases.push({id,result:check(actual)?'PASS':'FAIL',expected,actual});}
probe('approval-single-option',policy.selectInteraction({approval:true,options:['Approve']}),r=>r.kind!=='auto-select','Explicit approval remains required');
probe('native-picker-failed',policy.selectInteraction({approval:true,options,capabilities:{native_structured_choice:'supported'},failed_surfaces:['native-structured-choice']}),r=>r.kind==='markdown-numbered-choice','One stable numbered fallback after native failure');
probe('adapter-default-not-runtime-proof',policy.resolveAction({contract,adapter:'claude-code',action:'user.approve'}),r=>r.mode!=='native','Unobserved current tool exposure does not enable native');
probe('numeric',policy.normalizeChoiceResponse('1',localized),r=>r.selected==='Duyệt','Numeric selector selects approval');
probe('localized-short-equivalent',policy.normalizeChoiceResponse('duyệt', ['Duyệt spec','Yêu cầu chỉnh sửa','Hủy']),r=>r.selected==='Duyệt spec','Clear localized approval is accepted for the sole presented gate');
probe('ambiguous-numbers',policy.normalizeChoiceResponse('1 hoặc 2',localized),r=>r.status==='ambiguous','Ambiguous options do not resolve');
probe('silence',policy.normalizeChoiceResponse('',localized),r=>r.status==='ambiguous','Silence does not resolve approval');
probe('thanks',policy.normalizeChoiceResponse('cảm ơn',localized),r=>r.status==='ambiguous','Thanks is not approval');
probe('negative-containing-number',policy.normalizeChoiceResponse('không chọn 1',localized),r=>r.status!=='selected','A negated selector is not approval');
probe('native-unavailable',policy.selectInteraction({approval:true,options,capabilities:{native_structured_choice:'unsupported'}}),r=>r.kind==='markdown-numbered-choice','Unavailable native uses numbered fallback');
const inputs=['_refs/harness/runtime-policy.mjs','_refs/harness/capability-contract.json','_refs/shared/user-choice-prompt.md','_refs/shared/finish-gate.md'];
const record={source_revision:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),dirty_state:execFileSync('git',['status','--porcelain'],{encoding:'utf8'}).trim(),command:'node <TEMP>/interaction-finish-baseline.mjs',source_manifest:inputs.map(p=>({path:p,sha256:createHash('sha256').update(fs.readFileSync(p)).digest('hex')})),cases,limitation:'Deterministic policy probes; no live native surface or provider invocation. No production source edits.'};
fs.writeFileSync(path.join(process.env.TEMP,'interaction-finish-baseline.json'),JSON.stringify(record,null,2));
console.log(JSON.stringify({source_revision:record.source_revision,dirty_state:record.dirty_state,passed:cases.filter(x=>x.result==='PASS').length,failed:cases.filter(x=>x.result==='FAIL').length,cases},null,2));
